def tally_by_forager(trials):
    tally = {}
    for row in trials:
        forager = row["forager_id"]
        counts = tally.setdefault(forager, {"trials": 0, "bright": 0})
        counts["trials"] += 1
        if row["first_visit_choice"] == BRIGHT_LABEL:
            counts["bright"] += 1
    return tally
